vec4 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv); }
vec4 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv); }
vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

//we do everything for the next pixel.
vec2 r_uv_orig=vUvOriginal;
vec2 r_uv=vUv;
vUvOriginal=vec2(vUvOriginal.x+0.005,vUvOriginal.y);
vUv=vec2(vUv.x+0.005,vUv.y);
ret=GetPixel(vUvOriginal);
//1st stage
float n_size = 0.005;
int exist_count=0;
exist_count += (lum(GetPixel(vUv+n_size*vec2( 1, 1)))>=0.7);
exist_count += (lum(GetPixel(vUv+n_size*vec2( 1, 0)))>=0.7);
exist_count += (lum(GetPixel(vUv+n_size*vec2( 1,-1)))>=0.7);
