exist_count += (lum(GetPixel(vUv+n_size*vec2(-1, 0)))>=0.7);
exist_count += (lum(GetPixel(vUv+n_size*vec2(-1,-1)))>=0.7);
ret.z+=ret.x*0.1;
vec3 noise=-0.5*texture(sampler_noise_lq,vUv*rand_frame.xy);
if(ret.z>=0.89)
{ret.z=0;
ret.x+=noise*1.5;
};
ret+=exist_count;
ret.z=ret.z*0.9-0.06;
//2nd stage
ret.y=abs(vUv-vUvOriginal);
ret.x+=noise*0.05;

  fragColor = ret;
}

